INSERT INTO article_references VALUES('REF-2026-06-03-000050','10.1234/synth.complexity-load-001.9.5779','Interoception modulates cognitive restoration in adults: a empirical study (5779)','interoception modulates cognitive restoration in adults a empirical study 5779','T.',2018,'Frontiers in Psychology','mock_synthetic',NULL,'("Environmental complexity & cognitive" OR "prediction error") AND ("architectural space" OR "visual environment") AND ("Environmental complexity & cognitive" OR "cognitive load") -review','run-78b70603124d','abstract_collected','EDGE_CASE','borderline match on Nature and Attention; hits=[green space,biophilic,attention,cognitive restoration]',0.660000000000000031,'2026-06-03T17:28:54.219Z','{"synthetic": true, "kind": "empirical"}','We investigated whether interoception influences cognitive restoration. Randomized controlled trial with N=209. Built environment, green space, biophilic design, attention. p < 0.05.','We investigated whether interoception influences cognitive restoration. Randomized controlled trial with N=209. Built environment, green space, biophilic design, attention. p < 0.05.','search_payload','COMPLEXITY-LOAD-001',0.5300000000000000266,0,NULL,NULL,NULL,NULL,'2026-06-03T17:28:54.361Z');
INSERT INTO article_references VALUES('REF-test-1','10.1234/dup-test','Title X','title x',NULL,NULL,NULL,'serpapi_scholar',NULL,'q','run1','metadata_only',NULL,NULL,NULL,'2026-06-03T17:28:54.468Z',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,'2026-06-03T17:28:54.468Z');
INSERT INTO article_references VALUES('REF-RM-001','10.1186/s41235-020-00243-4','Senses of place: architectural design for the multisensory mind',NULL,NULL,NULL,NULL,'openalex_search',NULL,NULL,NULL,'acquired','ACCEPT',NULL,NULL,'2026-06-04T20:02:42.391Z','Charles Spence (2020). Senses of place: architectural design for the multisensory mind.',NULL,'Traditionally, architectural practice has been dominated by the eye/sight. In recent decades, though, architects and designers have increasingly started to consider the other senses, namely sound, touch (including proprioception, kinesthesis, and the vestibular sense), smell, and on rare occasions, even taste in their work. As yet, there has been little recognition of the growing understanding of the multisensory nature of the human mind that has emerged from the field of cognitive neuroscience research. This review therefore provides a summary of the role of the human senses in architectural design practice, both when considered individually and, more importantly, when studied collectively. For it is only by recognizing the fundamentally multisensory nature of perception that one can really hope to explain a number of surprising crossmodal environmental or atmospheric interactions, such as between lighting colour and thermal comfort and between sound and the perceived safety of public space. At the same time, however, the contemporary focus on synaesthetic design needs to be reframed in terms of the crossmodal correspondences and multisensory integration, at least if the most is to be made of multisensory interactions and synergies that have been uncovered in recent years. Looking to the future, the hope is that architectural design practice will increasingly incorporate our growing understanding of the human senses, and how they influence one another. Such a multisensory approach will hopefully lead to the development of buildings and urban spaces that do a better job of ','openalex','GAP-ROOM-HEIGHT',0.8000000000000000444,0,NULL,'paper:REF-RM-001','task3/data/pdfs/REF-RM-001.pdf','f690b90eacd3e48345b7401f2c25bad0135fa1aa696a48e5b07a4a090d7561cc','2026-06-04T20:02:42.391Z');
INSERT INTO article_references VALUES('REF-RM-002','10.3389/feduc.2020.00089','Innovative Learning Spaces in the Making',NULL,NULL,NULL,NULL,'openalex_search',NULL,NULL,NULL,'acquired','ACCEPT',NULL,NULL,'2026-06-04T20:02:42.591Z','Janette Hughes et al. (2020). Innovative Learning Spaces in the Making.',NULL,'This article details a qualitative, case study focusing on the affordances of innovative makerspaces for teaching and learning. The theoretical perspectives framing the research include embodied learning, materiality, neuroarchitecture and structuralism as it relates to power, inclusion and engagement within a learning space. Findings provide an overview of how the physical space (including the architecture of, and the furniture and materials within, the space) became an actor in the learning process. Three schools are highlighted as the case study examples. A detailed overview is provided of each of the spaces and the findings are supported through rich descriptions and a variety of data sources (i.e. teacher quotes, Twitter posts, images). This study is timely given that many Ontario schools have been and continue to build makerspaces to respond to the need to develop students’ global skills and competencies (critical thinking; innovation and creativity; self-directed learning; collaboration; communication and citizenship).','openalex','GAP-ROOM-HEIGHT',0.8000000000000000444,0,NULL,'paper:REF-RM-002','task3/data/pdfs/REF-RM-002.pdf','c66bf63da655d3e2e26f9ac167bddae9b2aef18189152940bf15c9c42e0cedec','2026-06-04T20:02:42.591Z');
INSERT INTO article_references VALUES('REF-RM-003','10.3390/s24237838','Brain and Subjective Responses to Indoor Environments Related to Concentration and Creativity',NULL,NULL,NULL,NULL,'claude_in_chrome',NULL,NULL,NULL,'acquired','ACCEPT',NULL,NULL,'2026-06-04T20:02:42.795Z','Zeyu Wang et al. (2024). Brain and Subjective Responses to Indoor Environments Related to Concentration and Creativity.',NULL,'Electroencephalograms (EEGs) can be used to study the influence of environmental elements on human emotions, cognition, and behavior. EEGs can reveal unconscious responses and fill in the gaps left by subjective responses provided in survey questionnaires or interviews. EEG research on the impact of classroom design elements on concentration and creativity is scarce; the design elements studied have not been diverse enough. In addition, no researchers have examined the brain and subjective responses to multiple indoor environmental elements regarding concentration and creativity. Thus, the purpose of this study was to explore how the human brain responds to different indoor environmental elements as shown by objective EEG signals related to concentration and creativity, and their similarities and differences to subjective self-reported responses. The experimental stimuli included 16 images combining four indoor environmental elements-classroom space shape, furniture arrangement, ceiling height, and color-along with images of white walls, a full-window wall with a view of nature, and a windowless scenario, totaling 19 images. The brainwaves of 20 people collected from eight channels were analyzed to determine the concentration index (CI) for concentration and relative theta (RT) for creativity. As a subjective response, participants were asked to choose the stimuli in which they felt they could best concentrate and be most creative in a self-report format. The results showed the following tendencies: (a) More brainwaves in the parietal and occipital lobes than in the prefron','openalex','GAP-ROOM-HEIGHT',0.8000000000000000444,0,NULL,'paper:REF-RM-003','task3/data/pdfs/REF-RM-003.pdf','f404fd9263b114854abc086174525820517ec8211b36e124aade47c172224dd2','2026-06-04T20:02:42.795Z');
INSERT INTO article_references VALUES('REF-10-3390-S21062193','10.3390/s21062193','The Cognitive-Emotional Design and Study of Architectural Space: A Scoping Review of Neuroarchitecture and Its Precursor Approaches',NULL,NULL,NULL,NULL,'claude_in_chrome',NULL,NULL,NULL,'acquired','ACCEPT',NULL,NULL,'2026-06-04T21:18:14.616Z','Juan Luis Higuera-Trujillo et al. (2021). The Cognitive-Emotional Design and Study of Architectural Space: A Scoping Review of Neuroarchitecture and Its Precursor Approaches.',NULL,'Humans respond cognitively and emotionally to the built environment. The modern possibility of recording the neural activity of subjects during exposure to environmental situations, using neuroscientific techniques and virtual reality, provides a promising framework for future design and studies of the built environment. The discipline derived is termed "neuroarchitecture". Given neuroarchitecture''s transdisciplinary nature, it progresses needs to be reviewed in a contextualised way, together with its precursor approaches. The present article presents a scoping review, which maps out the broad areas on which the new discipline is based. The limitations, controversies, benefits, impact on the professional sectors involved, and potential of neuroarchitecture and its precursors'' approaches are critically addressed.','openalex','GAP-ASSISTED',0.8000000000000000444,0,NULL,'paper:REF-10-3390-S21062193','task3/data/pdfs/REF-10-3390-S21062193.pdf','12278471c89a02a74b5d10bee10db0b6028f34b5b678cec2acd963fc1d0bf943','2026-06-04T21:18:14.616Z');
